@code {
    [Parameter] public NotificationPrefs? Prefs { get; set; }
    [Parameter] public EventCallback<NotificationPrefs> OnSave { get; set; }

    private bool EmailNotifications;
    private bool PushNotifications;
    private bool WeeklyDigest;
    private HashSet<string> MutedSet = new();
    private List<string> AllChannels = new();
    private bool IsSaving;
    private bool ShowSuccess;
    private bool _initialized;

    protected override void OnParametersSet()
    {
        if (Prefs is not null && !_initialized)
        {
            LoadFromPrefs(Prefs);
            _initialized = true;
        }
    }

    private void LoadFromPrefs(NotificationPrefs p)
    {
        EmailNotifications = p.EmailNotifications;
        PushNotifications = p.PushNotifications;
        WeeklyDigest = p.WeeklyDigest;
        AllChannels = new List<string>(p.MutedChannels);
        MutedSet = new HashSet<string>(p.MutedChannels);
    }

    private void ToggleMute(string channel, bool isMuted)
    {
        if (isMuted)
            MutedSet.Add(channel);
        else
            MutedSet.Remove(channel);
    }

    private async Task SaveAsync()
    {
        IsSaving = true;
        ShowSuccess = false;
        var updated = new NotificationPrefs(
            EmailNotifications, PushNotifications, WeeklyDigest,
            MutedSet.ToList());
        await OnSave.InvokeAsync(updated);
        IsSaving = false;
        ShowSuccess = true;
        _ = HideSuccessAfterDelay();
    }

    private async Task HideSuccessAfterDelay()
    {
        await Task.Delay(3000);
        ShowSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

@using sv_f9f4544ba36c4a6d968d7cf00c41918d.Models

<div class="settings-section">
    <h4>Security</h4>
    <hr />

    @if (Settings is not null)
    {
        <!-- Change Password -->
        <div class="card mb-4">
            <div class="card-header d-flex justify-content-between align-items-center"
                 style="cursor: pointer;" @onclick="() => PasswordPanelOpen = !PasswordPanelOpen">
                <span>🔑 Change Password</span>
                <span>@(PasswordPanelOpen ? "▲" : "▼")</span>
            </div>
            @if (PasswordPanelOpen)
            {
                <div class="card-body">
                    <div class="mb-3">
                        <label class="form-label">Current Password</label>
                        <input type="password" class="form-control" @bind="CurrentPassword" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">New Password</label>
                        <input type="password" class="form-control" @bind="NewPassword" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Confirm New Password</label>
                        <input type="password" class="form-control" @bind="ConfirmPassword" />
                    </div>

                    @if (!string.IsNullOrEmpty(PasswordError))
                    {
                        <div class="alert alert-danger">@PasswordError</div>
                    }
                    @if (PasswordSuccess)
                    {
                        <div class="alert alert-success">✅ Password updated successfully!</div>
                    }

                    <button class="btn btn-warning" @onclick="ChangePasswordAsync" disabled="@IsChangingPassword">
                        @if (IsChangingPassword)
                        {
                            <span class="spinner-border spinner-border-sm me-1"></span>
                        }
                        Update Password
                    </button>
                </div>
            }
        </div>

        <!-- Two-Factor Authentication -->
        <div class="card mb-4">
            <div class="card-body d-flex justify-content-between align-items-center">
                <div>
                    <h6 class="mb-1">Two-Factor Authentication</h6>
                    <span class="badge @(TwoFactorEnabled ? "bg-success" : "bg-secondary")">
                        @(TwoFactorEnabled ? "Enabled" : "Disabled")
                    </span>
                    @if (Settings.LastPasswordChange.HasValue)
                    {
                        <small class="text-muted ms-2">
                            Last password change: @Settings.LastPasswordChange.Value.ToString("MMM dd, yyyy")
                        </small>
                    }
                </div>
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" id="twoFactor"
                           checked="@TwoFactorEnabled"
                           @onchange="e => TwoFactorEnabled = (bool)e.Value!" />
                </div>
            </div>
        </div>

        <!-- Active Sessions -->
        <div class="card mb-4">
            <div class="card-header">
                <h6 class="mb-0">Active Sessions</h6>
            </div>
            <div class="card-body p-0">
                <table class="table table-hover mb-0">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th></th>
                        </tr>
                    </thead>
                    <tbody>
                        @foreach (var session in Settings.Sessions)
                        {
                            var isCurrent = session.Id == Settings.Sessions.FirstOrDefault()?.Id;
                            <tr>
                                <td>
                                    @session.Device
                                    @if (isCurrent)
                                    {
                                        <span class="badge bg-info ms-1">Current</span>
                                    }
                                </td>
                                <td>@session.Location</td>
                                <td>@FormatLastActive(session.LastActive)</td>
                                <td>
                                    @if (!isCurrent)
                                    {
                                        <button class="btn btn-outline-danger btn-sm"
                                                @onclick="() => PromptRevoke(session)">
                                            Revoke
                                        </button>
                                    }
                                </td>
                            </tr>
                        }
                    </tbody>
                </table>
            </div>
        </div>

        <!-- Revoke Confirmation Dialog -->
        @if (SessionToRevoke is not null)
        {
            <div class="modal-backdrop fade show"></div>
            <div class="modal fade show d-block" tabindex="-1" role="dialog">
                <div class="modal-dialog modal-dialog-centered">
                    <div class="modal-content">
                        <div class="modal-header">
                            <h5 class="modal-title">Revoke Session</h5>
                            <button type="button" class="btn-close" @onclick="CancelRevoke"></button>
                        </div>
                        <div class="modal-body">
                            <p>Are you sure you want to revoke this session?</p>
                            <p class="mb-0">
                                <strong>@SessionToRevoke.Device</strong> — @SessionToRevoke.Location
                            </p>
                        </div>
                        <div class="modal-footer">
                            <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                            <button class="btn btn-danger" @onclick="ConfirmRevokeAsync" disabled="@IsRevoking">
                                @if (IsRevoking)
                                {
                                    <span class="spinner-border spinner-border-sm me-1"></span>
                                }
                                Revoke
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        }
    }
</div>

@code {
    [Parameter] public SecuritySettings? Settings { get; set; }
    [Parameter] public EventCallback<(string currentPassword, string newPassword)> OnChangePassword { get; set; }
    [Parameter] public EventCallback<string> OnRevokeSession { get; set; }

    private bool PasswordPanelOpen;
    private string CurrentPassword = "";
    private string NewPassword = "";
    private string ConfirmPassword = "";
    private string? PasswordError;
    private bool PasswordSuccess;
    private bool IsChangingPassword;
    private bool TwoFactorEnabled;
    private ActiveSession? SessionToRevoke;
    private bool IsRevoking;

    protected override void OnParametersSet()
    {
        if (Settings is not null)
        {
            TwoFactorEnabled = Settings.TwoFactorEnabled;
        }
    }

    private async Task ChangePasswordAsync()
    {
        PasswordError = null;
        PasswordSuccess = false;

        if (string.IsNullOrWhiteSpace(CurrentPassword))
        {
            PasswordError = "Current password is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(NewPassword) || NewPassword.Length < 8)
        {
            PasswordError = "New password must be at least 8 characters.";
            return;
        }
        if (NewPassword != ConfirmPassword)
        {
            PasswordError = "New password and confirmation do not match.";
            return;
        }

        IsChangingPassword = true;
        await OnChangePassword.InvokeAsync((CurrentPassword, NewPassword));
        IsChangingPassword = false;
        PasswordSuccess = true;
        CurrentPassword = "";
        NewPassword = "";
        ConfirmPassword = "";
    }

    private void PromptRevoke(ActiveSession session) => SessionToRevoke = session;
    private void CancelRevoke() => SessionToRevoke = null;

    private async Task ConfirmRevokeAsync()
    {
        if (SessionToRevoke is null) return;
        IsRevoking = true;
        await OnRevokeSession.InvokeAsync(SessionToRevoke.Id);
        IsRevoking = false;
        SessionToRevoke = null;
    }

    private static string FormatLastActive(DateTime dt)
    {
        var diff = DateTime.UtcNow - dt;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }
}

@using sv_f9f4544ba36c4a6d968d7cf00c41918d.Models

<div class="settings-section">
    <h4>Appearance</h4>
    <hr />

    @if (Settings is not null)
    {
        <div class="row">
            <div class="col-md-7">
                <!-- Theme -->
                <div class="mb-4">
                    <h6>Theme</h6>
                    @foreach (var theme in new[] { "Light", "Dark", "System" })
                    {
                        <div class="form-check">
                            <input class="form-check-input" type="radio" name="theme" id="theme-@theme"
                                   checked="@(SelectedTheme == theme)"
                                   @onchange="() => SelectedTheme = theme" />
                            <label class="form-check-label" for="theme-@theme">@theme</label>
                        </div>
                    }
                </div>

                <!-- Font Size -->
                <div class="mb-4">
                    <h6>Font Size</h6>
                    @foreach (var size in new[] { "Small", "Medium", "Large" })
                    {
                        <div class="form-check">
                            <input class="form-check-input" type="radio" name="fontSize" id="fs-@size"
                                   checked="@(SelectedFontSize == size)"
                                   @onchange="() => SelectedFontSize = size" />
                            <label class="form-check-label" for="fs-@size">@size</label>
                        </div>
                    }
                </div>

                <!-- Language -->
                <div class="mb-4">
                    <h6>Language</h6>
                    <select class="form-select" style="max-width: 250px;"
                            @bind="SelectedLanguage">
                        @foreach (var lang in Languages)
                        {
                            <option value="@lang">@lang</option>
                        }
                    </select>
                </div>

                <!-- Compact Mode -->
                <div class="mb-4">
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" id="compactMode"
                               checked="@CompactMode"
                               @onchange="e => CompactMode = (bool)e.Value!" />
                        <label class="form-check-label" for="compactMode">Compact Mode</label>
                    </div>
                </div>

                <button class="btn btn-primary" @onclick="SaveAsync" disabled="@IsSaving">
                    @if (IsSaving)
                    {
                        <span class="spinner-border spinner-border-sm me-1"></span>
                    }
                    Save
                </button>

                @if (ShowSuccess)
                {
                    <div class="alert alert-success mt-3 fade show" role="alert">
                        ✅ Appearance settings saved!
                    </div>
                }
            </div>

            <!-- Live Preview -->
            <div class="col-md-5">
                <div class="card appearance-preview @PreviewThemeClass" style="@PreviewFontStyle">
                    <div class="card-header">
                        <strong>Live Preview</strong>
                    </div>
                    <div class="card-body @(CompactMode ? "p-2" : "")">
                        <h6 style="@PreviewFontStyle">Dashboard Header</h6>
                        <p class="@(CompactMode ? "mb-1" : "mb-3")" style="@PreviewFontStyle">
                            This is how your content will look with the selected settings.
                        </p>
                        <div class="d-flex gap-2 @(CompactMode ? "mb-1" : "mb-2")">
                            <span class="badge bg-primary">Tag One</span>
                            <span class="badge bg-secondary">Tag Two</span>
                        </div>
                        <button class="btn btn-sm btn-primary" disabled>Sample Button</button>
                        <div class="mt-2">
                            <small class="text-muted">
                                Theme: @SelectedTheme · Font: @SelectedFontSize · Lang: @SelectedLanguage
                                @(CompactMode ? " · Compact" : "")
                            </small>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public AppearanceSettings? Settings { get; set; }
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string SelectedTheme = "Light";
    private string SelectedFontSize = "Medium";
    private string SelectedLanguage = "English";
    private bool CompactMode;
    private bool IsSaving;
    private bool ShowSuccess;
    private bool _initialized;

    private static readonly string[] Languages =
        ["English", "Spanish", "French", "German", "Japanese", "Chinese", "Portuguese"];

    protected override void OnParametersSet()
    {
        if (Settings is not null && !_initialized)
        {
            SelectedTheme = Settings.Theme;
            SelectedFontSize = Settings.FontSize;
            SelectedLanguage = Settings.Language;
            CompactMode = Settings.CompactMode;
            _initialized = true;
        }
    }

    private string PreviewThemeClass => SelectedTheme switch
    {
        "Dark" => "bg-dark text-light",
        "System" => "bg-secondary bg-opacity-10",
        _ => "bg-white"
    };

    private string PreviewFontStyle => SelectedFontSize switch
    {
        "Small" => "font-size: 0.85rem;",
        "Large" => "font-size: 1.15rem;",
        _ => "font-size: 1rem;"
    };

    private async Task SaveAsync()
    {
        IsSaving = true;
        ShowSuccess = false;
        var updated = new AppearanceSettings(SelectedTheme, SelectedFontSize, SelectedLanguage, CompactMode);
        await OnSave.InvokeAsync(updated);
        IsSaving = false;
        ShowSuccess = true;
        _ = HideSuccessAfterDelay();
    }

    private async Task HideSuccessAfterDelay()
    {
        await Task.Delay(3000);
        ShowSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

