@using sv_f9f4544ba36c4a6d968d7cf00c41918d.Models

<div class="settings-section">
    <h4>Notifications</h4>
    <hr />

    @if (Prefs is not null)
    {
        <div class="mb-4">
            <h6>General</h6>
            <div class="form-check form-switch mb-2">
                <input class="form-check-input" type="checkbox" id="emailNotif"
                       checked="@EmailNotifications" @onchange="e => EmailNotifications = (bool)e.Value!" />
                <label class="form-check-label" for="emailNotif">Email Notifications</label>
            </div>
            <div class="form-check form-switch mb-2">
                <input class="form-check-input" type="checkbox" id="pushNotif"
                       checked="@PushNotifications" @onchange="e => PushNotifications = (bool)e.Value!" />
                <label class="form-check-label" for="pushNotif">Push Notifications</label>
            </div>
            <div class="form-check form-switch mb-2">
                <input class="form-check-input" type="checkbox" id="weeklyDigest"
                       checked="@WeeklyDigest" @onchange="e => WeeklyDigest = (bool)e.Value!" />
                <label class="form-check-label" for="weeklyDigest">Weekly Digest</label>
            </div>
        </div>

        <div class="mb-4">
            <h6>Muted Channels</h6>
            <p class="text-muted small">Uncheck a channel to unmute it.</p>
            @if (AllChannels.Count > 0)
            {
                @foreach (var channel in AllChannels)
                {
                    <div class="form-check mb-1">
                        <input class="form-check-input" type="checkbox" id="ch-@channel"
                               checked="@MutedSet.Contains(channel)"
                               @onchange="e => ToggleMute(channel, (bool)e.Value!)" />
                        <label class="form-check-label" for="ch-@channel">#@channel</label>
                    </div>
                }
            }
            else
            {
                <p class="text-muted">No channels available.</p>
            }
        </div>

        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@IsSaving">
            @if (IsSaving)
            {
                <span class="spinner-border spinner-border-sm me-1"></span>
            }
            Save Preferences
        </button>

        @if (ShowSuccess)
        {
            <div class="alert alert-success mt-3 fade show" role="alert">
                ✅ Notification preferences saved!
            </div>
        }
    }
</div>

@code {
    [Parameter] public NotificationPrefs? Prefs { get; set; }
    [Parameter] public EventCallback<NotificationPrefs> OnSave { get; set; }

    private bool EmailNotifications;
    private bool PushNotifications;
    private bool WeeklyDigest;
    private HashSet<string> MutedSet = new();
    private List<string> AllChannels = new();
    private bool IsSaving;
    private bool ShowSuccess;
    private bool _initialized;

    protected override void OnParametersSet()
    {
        if (Prefs is not null && !_initialized)
        {
            LoadFromPrefs(Prefs);
            _initialized = true;
        }
    }

    private void LoadFromPrefs(NotificationPrefs p)
    {
        EmailNotifications = p.EmailNotifications;
        PushNotifications = p.PushNotifications;
        WeeklyDigest = p.WeeklyDigest;
        AllChannels = new List<string>(p.MutedChannels);
        MutedSet = new HashSet<string>(p.MutedChannels);
    }

    private void ToggleMute(string channel, bool isMuted)
    {
        if (isMuted)
            MutedSet.Add(channel);
        else
            MutedSet.Remove(channel);
    }

    private async Task SaveAsync()
    {
        IsSaving = true;
        ShowSuccess = false;
        var updated = new NotificationPrefs(
            EmailNotifications, PushNotifications, WeeklyDigest,
            MutedSet.ToList());
        await OnSave.InvokeAsync(updated);
        IsSaving = false;
        ShowSuccess = true;
        _ = HideSuccessAfterDelay();
    }

    private async Task HideSuccessAfterDelay()
    {
        await Task.Delay(3000);
        ShowSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

