@page "/settings"
@using sv_f9f4544ba36c4a6d968d7cf00c41918d.Models
@using sv_f9f4544ba36c4a6d968d7cf00c41918d.Services
@using sv_f9f4544ba36c4a6d968d7cf00c41918d.Components.Pages.Settings
@rendermode InteractiveServer
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-layout">
    <SettingsSidebar ActiveSection="@activeSection" OnSectionChanged="SetActiveSection" />

    <div class="settings-content">
        @if (isLoading)
        {
            <div class="d-flex justify-content-center py-5">
                <div class="spinner-border" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
            </div>
        }
        else
        {
            @switch (activeSection)
            {
                case "Profile":
                    <ProfileSection Profile="@profile" OnSave="SaveProfileAsync" />
                    break;
                case "Notifications":
                    <NotificationsSection Prefs="@notificationPrefs" OnSave="SaveNotificationsAsync" />
                    break;
                case "Security":
                    <SecuritySection Settings="@securitySettings"
                                     OnChangePassword="ChangePasswordAsync"
                                     OnRevokeSession="RevokeSessionAsync" />
                    break;
                case "Appearance":
                    <AppearanceSection Settings="@appearanceSettings" OnSave="SaveAppearanceAsync" />
                    break;
            }
        }
    </div>
</div>

@code {
    private string activeSection = "Profile";
    private bool isLoading = true;

    private UserProfile? profile;
    private NotificationPrefs? notificationPrefs;
    private SecuritySettings? securitySettings;
    private AppearanceSettings? appearanceSettings;

    protected override async Task OnInitializedAsync()
    {
        await LoadSectionDataAsync();
    }

    private async Task SetActiveSection(string section)
    {
        activeSection = section;
        await LoadSectionDataAsync();
    }

    private async Task LoadSectionDataAsync()
    {
        isLoading = true;
        switch (activeSection)
        {
            case "Profile":
                profile = await SettingsService.GetProfileAsync();
                break;
            case "Notifications":
                notificationPrefs = await SettingsService.GetNotificationPrefsAsync();
                break;
            case "Security":
                securitySettings = await SettingsService.GetSecuritySettingsAsync();
                break;
            case "Appearance":
                appearanceSettings = await SettingsService.GetAppearanceAsync();
                break;
        }
        isLoading = false;
    }

    private async Task SaveProfileAsync(UserProfile updated)
    {
        await SettingsService.SaveProfileAsync(updated);
        profile = updated;
    }

    private async Task SaveNotificationsAsync(NotificationPrefs updated)
    {
        await SettingsService.SaveNotificationPrefsAsync(updated);
        notificationPrefs = updated;
    }

    private async Task ChangePasswordAsync((string currentPassword, string newPassword) args)
    {
        await SettingsService.ChangePasswordAsync(args.currentPassword, args.newPassword);
        securitySettings = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task RevokeSessionAsync(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        securitySettings = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task SaveAppearanceAsync(AppearanceSettings updated)
    {
        await SettingsService.SaveAppearanceAsync(updated);
        appearanceSettings = updated;
    }
}

.settings-layout {
    display: flex;
    gap: 1.5rem;
    min-height: 600px;
}

/* Sidebar */
.settings-sidebar {
    width: 220px;
    flex-shrink: 0;
    background: #f8f9fa;
    border-radius: 8px;
    padding: 1rem 0;
    border: 1px solid #e9ecef;
}

.sidebar-title {
    padding: 0 1rem 0.5rem;
    margin-bottom: 0.25rem;
    color: #6c757d;
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

.settings-sidebar .nav-link {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.6rem 1rem;
    color: #495057;
    border: none;
    background: none;
    width: 100%;
    text-align: left;
    font-size: 0.95rem;
    border-left: 3px solid transparent;
    transition: all 0.15s ease;
}

.settings-sidebar .nav-link:hover {
    background: #e9ecef;
    color: #212529;
}

.settings-sidebar .nav-link.active {
    background: #e7f1ff;
    color: #0d6efd;
    border-left-color: #0d6efd;
    font-weight: 600;
}

.sidebar-icon {
    font-size: 1.1rem;
}

/* Content area */
.settings-content {
    flex: 1;
    min-width: 0;
}

.settings-section h4 {
    margin-bottom: 0.25rem;
}

/* Avatar preview */
.avatar-preview img {
    object-fit: cover;
    border: 3px solid #e9ecef;
}

/* Appearance preview */
.appearance-preview {
    border: 1px solid #dee2e6;
    border-radius: 8px;
    transition: all 0.2s ease;
}

.appearance-preview.bg-dark {
    border-color: #495057;
}

